def compute(vars):
    total_thousand = vars["v1"] + vars["v2"] + vars["v3"] + vars["v4"]
    value = total_thousand / 1000
    return {
        "value": value,
        "trace": {
            "total_thousand": total_thousand,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
